L = {'mm':0.001,'cm':0.01,'m':1.0,'km':1000.0,'inch':0.0254,'ft':0.3048,'mi':1609.344}
W = {'mg':1e-6,'g':0.001,'kg':1.0,'t':1000.0,'lb':0.45359237,'oz':0.0283495}
